{
  "categoryId": "{{catId}}",
  "listingType": "BOTH",
  "version": 1,
  "isActive": true,
  "title": {
    "en": "List Equipment",
    "hi": "उपकरण सूचीबद्ध करें"
  },
  "fields": [
    {
      "fieldKey": "equipmentCategory",
      "type": "DROPDOWN",
      "label": {
        "en": "Equipment Category",
        "hi": "उपकरण श्रेणी"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "equipment__equipment_category",
      "editableOnUpdate": false
    },
    {
      "fieldKey": "equipmentName",
      "type": "DROPDOWN",
      "label": {
        "en": "Equipment Name",
        "hi": "उपकरण का नाम"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 20,
      "optionSetKey": "equipment__equipment_name",
      "parentField": "equipmentCategory",
      "editableOnUpdate": false,
      "visibleWhen": {
        "field": "equipmentCategory",
        "operator": "notEquals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "equipmentNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify Equipment Name",
        "hi": "कृपया उपकरण का नाम बताएं"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 30,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "equipmentCategory",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "availableFor",
      "type": "RADIO",
      "label": {
        "en": "Available For",
        "hi": "उपलब्ध है"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 40,
      "optionSetKey": "equipment__avail",
      "editableOnUpdate": false
    },
    {
      "fieldKey": "rentPerHour",
      "type": "DECIMAL",
      "label": {
        "en": "Rent Per Hour (₹)",
        "hi": "प्रति घंटा किराया (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 50,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "rent"
      }
    },
    {
      "fieldKey": "brandName",
      "type": "TEXT",
      "label": {
        "en": "Brand Name",
        "hi": "ब्रांड नाम"
      },
      "sectionKey": "seller",
      "sectionTitle": {
        "en": "Seller Details",
        "hi": "विक्रेता विवरण"
      },
      "required": false,
      "displayOrder": 60,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "modelNumber",
      "type": "TEXT",
      "label": {
        "en": "Model Number",
        "hi": "मॉडल नंबर"
      },
      "sectionKey": "seller",
      "sectionTitle": {
        "en": "Seller Details",
        "hi": "विक्रेता विवरण"
      },
      "required": false,
      "displayOrder": 70,
      "fieldLength": 60,
      "validation": {
        "maxLength": 60
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "modelYear",
      "type": "NUMBER",
      "label": {
        "en": "Model Year",
        "hi": "मॉडल वर्ष"
      },
      "sectionKey": "seller",
      "sectionTitle": {
        "en": "Seller Details",
        "hi": "विक्रेता विवरण"
      },
      "required": false,
      "displayOrder": 80,
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "availableQty",
      "type": "NUMBER",
      "label": {
        "en": "Available Quantity",
        "hi": "उपलब्ध मात्रा"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 90,
      "inlineEditable": true,
      "validation": {
        "min": 1
      }
    },
    {
      "fieldKey": "actualPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Actual Price (₹)",
        "hi": "वास्तविक मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 100,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "offeredPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Offered Price (₹)",
        "hi": "प्रस्तावित मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 110,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "discountPct",
      "type": "AUTO_CALC",
      "label": {
        "en": "Discount %",
        "hi": "छूट %"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 120,
      "common": true,
      "readOnly": true,
      "computed": {
        "formula": "((availableFor == \"rent\" ? rentPerHour : actualPrice) - offeredPrice) / (availableFor == \"rent\" ? rentPerHour : actualPrice) * 100",
        "readOnly": true
      }
    },
    {
      "fieldKey": "isNegotiable",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Negotiable?",
        "hi": "क्या मोल-भाव योग्य है?"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 130,
      "common": true
    },
    {
      "fieldKey": "images",
      "type": "IMAGE",
      "label": {
        "en": "Upload Images",
        "hi": "तस्वीरें अपलोड करें"
      },
      "sectionKey": "media",
      "sectionTitle": {
        "en": "Photos",
        "hi": "तस्वीरें"
      },
      "required": true,
      "displayOrder": 140,
      "multiple": true,
      "common": true,
      "validation": {
        "min": 1,
        "max": 10,
        "acceptedTypes": [
          "jpg",
          "png",
          "webp"
        ],
        "sources": [
          "camera",
          "gallery"
        ],
        "capture": true
      }
    },
    {
      "fieldKey": "contactNumber",
      "type": "TEXT",
      "label": {
        "en": "Contact Number",
        "hi": "संपर्क नंबर"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": true,
      "displayOrder": 150,
      "common": true,
      "fieldLength": 10,
      "validation": {
        "regex": "^[6-9][0-9]{9}$",
        "maxLength": 10
      }
    },
    {
      "fieldKey": "showContact",
      "type": "BOOLEAN",
      "label": {
        "en": "Show my contact number & address to buyers",
        "hi": "मेरा संपर्क नंबर और पता खरीदारों को दिखाएं"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": false,
      "displayOrder": 160,
      "help": {
        "en": "If off, your number and full address stay hidden — buyers must send a contact request that you approve before they are revealed.",
        "hi": "यदि बंद है, तो आपका नंबर और पूरा पता छिपा रहेगा — खरीदार संपर्क अनुरोध भेजेंगे और आपकी स्वीकृति के बाद ही ये दिखेंगे।"
      },
      "common": true
    }
  ]
}

